# Pseudocode for data augmentation pipeline
import random

def augment(image, label):
    if random.random() > 0.5:
        image = flip_horizontal(image)
    if random.random() > 0.5:
        image = rotate(image, random.randint(-15, 15))
    if random.random() > 0.5:
        image = color_jitter(image, brightness=0.2, contrast=0.2)
    return image, label

# Example usage
augmented_image, augmented_label = augment(original_image, original_label)
